import { useEffect,useState } from 'react'
import api from '../../services/api'
import LoadingSpinner from '../../components/LoadingSpinner'
export default function VendorDashboard(){const [stats,setStats]=useState(null);const [error,setError]=useState('');const load=()=>api.get('/api/vendor/dashboard').then(({data})=>{setStats(data);setError('')}).catch(e=>setError(e.response?.data?.detail||'Unable to load the vendor dashboard.'));useEffect(()=>{load()},[]);if(error)return <div className="state-panel error-state"><strong>{error}</strong><button onClick={load}>Retry</button></div>;if(!stats)return <LoadingSpinner label="Loading dashboard..."/>;return <><span className="section-kicker">ChanGu Vendor Dashboard</span><h1 className="vendor-title">Your business at a glance.</h1><div className="stats-grid">{[['Total Orders',stats.total_orders],['Pending Orders',stats.pending_orders],['Completed Orders',stats.completed_orders],['Today Sales',`₹${stats.today_sales}`],['Products',stats.total_products],['Low Stock',stats.low_stock_products]].map(([label,value])=><div className="stat-card" key={label}><small>{label}</small><strong>{value}</strong></div>)}</div><div className="vendor-actions"><a href="/vendor/products">+ Add Product</a><a href="/vendor/orders">View Orders</a><a href="/vendor/store">Manage Store</a></div></>}
